##
## Undocumented internal function for the wasm pkg integration.

## Create the `packinfo/` subdirectory that `pkg install` would have created.
##
## Upstream `install.m` (lines 588-610) copies these files from the unpacked
## package into `<installdir>/packinfo/`:
##
##     DESCRIPTION  COPYING   (required)
##     CITATION  NEWS  ONEWS  ChangeLog   (optional)
##     INDEX   (copied if present, otherwise generated by write_index)
##
## and `describe.m`'s `parse_pkg_idx` reads `<dir>/packinfo/INDEX` specifically.
## This build's asset bundles ship those files at the *package root* instead
## (they emulate `inst/` up-lifting, not the packinfo step), so the directory has
## to be materialized before `pkg describe` can work.
##
## Copies rather than symlinks, and skips anything already present: the sync runs
## on every page load and must be idempotent and cheap.  Returns the number of
## files placed.
##
## The copy is done with plain fopen/fread/fwrite rather than the `copyfile`
## override from build/webfile: that override is a lazily-loaded asset, so
## depending on it here would make the pkg sync work or fail according to which
## assets happened to be loaded first.  These files are small and textual, but
## the read is still binary-safe so a stray non-ASCII byte cannot corrupt them.

function n = __pkgfix_make_packinfo__ (pkgdir)

  n = 0;
  if (! isfolder (pkgdir))
    return;
  endif

  pi = fullfile (pkgdir, "packinfo");
  if (! isfolder (pi))
    mkdir (pi);
  endif

  ## Names taken verbatim from install.m's packinfo_copy_file calls.
  wanted = {"DESCRIPTION", "COPYING", "CITATION", "NEWS", "ONEWS", "ChangeLog", "INDEX"};
  for k = 1:numel (wanted)
    nm = wanted{k};
    src = fullfile (pkgdir, nm);
    dst = fullfile (pi, nm);
    ## Absent optional file: nothing to do.  A missing INDEX is the one that
    ## actually breaks `pkg describe`; the acceptance test checks that case
    ## rather than this function guessing.
    if (! exist (src, "file") || exist (dst, "file"))
      continue;
    endif
    fin = fopen (src, "rb");
    if (fin < 0)
      continue;
    endif
    buf = fread (fin, Inf, "*uint8");
    fclose (fin);
    fout = fopen (dst, "wb");
    if (fout < 0)
      continue;
    endif
    fwrite (fout, buf, "uint8");
    fclose (fout);
    n = n + 1;
  endfor

endfunction


%!test
%! ## The files present at the package root land in packinfo/.
%! d = tempname (); mkdir (d);
%! for f = {"DESCRIPTION", "COPYING", "INDEX"}
%!   fid = fopen (fullfile (d, f{1}), "w"); fputs (fid, "x"); fclose (fid);
%! endfor
%! n = __pkgfix_make_packinfo__ (d);
%! assert (n, 3);
%! assert (exist (fullfile (d, "packinfo", "INDEX"), "file"), 2);
%! assert (exist (fullfile (d, "packinfo", "DESCRIPTION"), "file"), 2);

%!test
%! ## Idempotent: a second call places nothing.
%! d = tempname (); mkdir (d);
%! fid = fopen (fullfile (d, "INDEX"), "w"); fputs (fid, "x"); fclose (fid);
%! assert (__pkgfix_make_packinfo__ (d), 1);
%! assert (__pkgfix_make_packinfo__ (d), 0);

%!test
%! ## A missing directory is a no-op, not an error.
%! assert (__pkgfix_make_packinfo__ ("/no/such/dir"), 0);
